import { UIContext, useUIStore } from "./runtime/store.js";
import MainPage from "./pages/MainPage.jsx";
import LoginPage from "./pages/LoginPage.jsx";

const PAGES = {
  page_main: MainPage,
  page_login: LoginPage,
};

const INITIALLY_HIDDEN = {};

export default function App() {
  const ui = useUIStore("page_main", INITIALLY_HIDDEN);
  const CurrentPage = PAGES[ui.page] ?? MainPage;

  return (
    <UIContext.Provider value={ui}>
      <div className="ng-app">
        <CurrentPage />
      </div>
    </UIContext.Provider>
  );
}

